const fullNameInput = document.getElementById('fullName');
const emailInput = document.getElementById('email');
const phoneInput = document.getElementById('phone');

const fullNameError = document.getElementById('fullNameError');
const emailError = document.getElementById('emailError');
const phoneError = document.getElementById('phoneError');

const inputs = {
  fullName: { element: fullNameInput, errorElement: fullNameError },
  email: { element: emailInput, errorElement: emailError },
  phone: { element: phoneInput, errorElement: phoneError }
};

function validateFullName(value) {
  if (!value.trim()) {
    return 'Full name is required.';
  }
  if (value.trim().length < 2) {
    return 'Full name must be at least 2 characters.';
  }
  return '';
}

function validateEmail(value) {
  if (!value.trim()) {
    return 'Email address is required.';
  }
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(value)) {
    return 'Please enter a valid email address.';
  }
  return '';
}

function validatePhone(value) {
  if (!value.trim()) {
    return '';
  }
  const phoneRegex = /^[\+]?[(]?[0-9]{3}[)]?[-\s\.]?[0-9]{3}[-\s\.]?[0-9]{4,6}$/;
  if (!phoneRegex.test(value)) {
    return 'Please enter a valid phone number (e.g., +1 (555) 123-4567).';
  }
  return '';
}

function validateField(fieldName) {
  const input = inputs[fieldName].element;
  const errorElement = inputs[fieldName].errorElement;
  let error = '';

  if (fieldName === 'fullName') {
    error = validateFullName(input.value);
  } else if (fieldName === 'email') {
    error = validateEmail(input.value);
  } else if (fieldName === 'phone') {
    error = validatePhone(input.value);
  }

  errorElement.textContent = error;

  if (error) {
    input.classList.add('invalid');
    input.classList.remove('valid');
  } else if (input.value.trim()) {
    input.classList.remove('invalid');
    input.classList.add('valid');
  } else {
    input.classList.remove('invalid');
    input.classList.remove('valid');
  }

  return !error;
}

function validateForm() {
  const isFullNameValid = validateField('fullName');
  const isEmailValid = validateField('email');
  const isPhoneValid = validateField('phone');

  return isFullNameValid && isEmailValid && isPhoneValid;
}

fullNameInput.addEventListener('blur', () => {
  validateField('fullName');
});

emailInput.addEventListener('blur', () => {
  validateField('email');
});

phoneInput.addEventListener('blur', () => {
  validateField('phone');
});

fullNameInput.addEventListener('input', () => {
  if (fullNameInput.classList.contains('invalid')) {
    validateField('fullName');
  }
});

emailInput.addEventListener('input', () => {
  if (emailInput.classList.contains('invalid')) {
    validateField('email');
  }
});

phoneInput.addEventListener('input', () => {
  if (phoneInput.classList.contains('invalid')) {
    validateField('phone');
  }
});

form.addEventListener('submit', (e) => {
  e.preventDefault();

  if (validateForm()) {
    const formData = {
      fullName: fullNameInput.value.trim(),
      email: emailInput.value.trim(),
      phone: phoneInput.value.trim() || null
    };

    console.log('Form submitted successfully:', formData);
    alert('Thank you for contacting us! We will get back to you soon.');
    form.reset();
    fullNameInput.classList.remove('valid', 'invalid');
    emailInput.classList.remove('valid', 'invalid');
    phoneInput.classList.remove('valid', 'invalid');
    fullNameError.textContent = '';
    emailError.textContent = '';
    phoneError.textContent = '';
  }
});
